        report = self.batch([
            {"id": "x", "certificate": self.good, "rounds": self.rounds},
        ])
        self.assertEqual(set(report.keys()), {"items", "version"})
        self.assertEqual(report["version"], 1)
        self.assertEqual(report["items"][0]["result"]["status"], "confirmed")

